def _p95(vals):
    """선형보간 P95 (순수 파이썬 — numpy 의존 없음). §5 N10: K1·K2 요약 = P95."""
    v = sorted(x for x in vals if x is not None)
    if not v:
        return None
    if len(v) == 1:
        return v[0]
    pos = 0.95 * (len(v) - 1)
    lo = int(pos)
    hi = min(lo + 1, len(v) - 1)
    frac = pos - lo
    return v[lo] * (1.0 - frac) + v[hi] * frac


def estimate_u(recs, mode: str, ratios=(0.10, 0.30), abs_u=None):
    """u 추정 (§6.1 A안/B안) — **지표별 dict** 를 돌려준다.

    A안(absolute): `abs_u` = {"k1": mm_P95, "k2": mm/s_P95} (둘 다 필요).
                   치구 거리오차(mm)를 속도(mm/s)에 전용할 수 없다(§5 N17).
    B안(ratio)   : 각 지표 **기저 P95 × 비율**. 단위 안전(항상 가능).
    """
    if abs_u is not None:
        return {"k1": float(abs_u["k1"]), "k2": float(abs_u["k2"])}
    ratio = max(ratios)
    out = {}
    for m, f in (("k1", "k1_raw_mm"), ("k2", "k2_raw_mm")):
        out[m] = None if _p95([r.get(f) for r in recs]) is None \
            else _p95([r.get(f) for r in recs]) * ratio
    return out

